(()=>{
const el=id=>document.getElementById(id),status=el('folderStatus'),choose=el('chooseFolder'),resume=el('resumeFolder'),stop=el('stopFolder');
let config=null,handleDB=null,queue=Promise.resolve(),pending=0,generation=0;
const supported='showDirectoryPicker' in window;
const setStatus=(text,error=false)=>{status.textContent=text;status.classList.toggle('backup-error',error)};
const buttons=()=>{resume.hidden=!config;stop.hidden=!config;};
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('ram-erp-folder-backup',1);r.onupgradeneeded=()=>r.result.createObjectStore('settings');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function readConfig(){return new Promise((resolve,reject)=>{const r=handleDB.transaction('settings').objectStore('settings').get('folder');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function storeConfig(value){return new Promise((resolve,reject)=>{const tx=handleDB.transaction('settings','readwrite');const os=tx.objectStore('settings');value?os.put(value,'folder'):os.delete('folder');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function snapshot(data){return JSON.stringify({version:1,backedUpAt:new Date().toISOString(),items:data.items,suppliers:data.suppliers||[],customers:data.customers||[],invoices:data.invoices},null,2)}
function schedule(data){if(!config)return;const text=snapshot(data),selected=config,token=generation;pending++;setStatus('Saving backup to '+selected.directory.name+'…');queue=queue.then(async()=>{if(token!==generation)return;let stream;try{if(await selected.directory.queryPermission({mode:'readwrite'})!=='granted'){setStatus('Backup paused. Click Resume backup and allow folder access.',true);return;}let file=await selected.directory.getFileHandle(selected.filename,{create:true});stream=await file.createWritable();await stream.write(text);await stream.close();stream=null;if(token===generation)setStatus('Saved '+new Date().toLocaleTimeString()+' · '+selected.directory.name+' / '+selected.filename);}catch(e){if(stream)try{await stream.abort()}catch(_){}if(token===generation)setStatus('Backup failed. Check the drive and folder permission, then click Resume backup. Your browser copy is still saved.',true);}finally{}}).finally(()=>{pending--});}
const saveBrowser=persist;persist=function(next){const ok=saveBrowser(next);if(ok)schedule(next);return ok;};
choose.onclick=async()=>{try{const directory=await window.showDirectoryPicker({id:'ram-erp-backup',mode:'readwrite'});generation++;config={directory,filename:'RAM-ERP-backup-'+new Date().toISOString().replace(/[:.]/g,'-')+'-'+crypto.randomUUID().slice(0,8)+'.json'};buttons();if(handleDB){try{await storeConfig(config)}catch(e){toast('Folder works this session. Select it again next time.')}}schedule(db);}catch(e){if(e.name!=='AbortError')setStatus('Could not open this folder. Open the app directly in Chrome or Edge and select an accessible folder.',true)}};
resume.onclick=async()=>{if(!config)return;try{const permission=await config.directory.requestPermission({mode:'readwrite'});if(permission!=='granted')return setStatus('Folder permission is required. Browser data is still saved.',true);schedule(db);}catch(e){setStatus('Folder unavailable. Connect the drive or select the folder again.',true)}};
stop.onclick=async()=>{generation++;config=null;buttons();try{if(handleDB)await storeConfig(null)}catch(e){}setStatus('Automatic folder backup is off. Existing backup files are kept.');};
window.addEventListener('beforeunload',e=>{if(pending){e.preventDefault();e.returnValue=''}});
buttons();
if(!supported){choose.disabled=true;setStatus('Folder backup is not supported in this browser. Open this app in Chrome or Edge on your Windows computer, or use Download backup.');return;}
openDB().then(async database=>{handleDB=database;config=await readConfig()||null;buttons();if(config){if(await config.directory.queryPermission({mode:'readwrite'})==='granted'){setStatus('Folder connected · '+config.directory.name+'. New changes will be backed up automatically.');}else setStatus('Backup paused. Click Resume backup to allow access to '+config.directory.name+'.',true);}}).catch(()=>{setStatus('Choose a folder to back up this session. Your browser cannot remember the folder after closing.');});
})();
